const query = $input.item.json.query || {};
const rowNumber = query.row_number;
const action = query.action;

if (!rowNumber || !action) {
  throw new Error('Faltan parámetros: row_number o action');
}

return {
  row_number: parseInt(rowNumber, 10),
  action: action
};

const filas = $input.all().map(i => i.json);
const rowNumber = $('Procesar parámetros').first().json.row_number;

const fila = filas.find(f => f.row_number == rowNumber);

if (!fila) {
  throw new Error(`No se encontró la fila con row_number=${rowNumber}`);
}

return {
  ...fila,
  row_number: rowNumber,
  action: $('Procesar parámetros').first().json.action
};

const data = $input.first().json;
const action = data.action;
const rowNumber = data.row_number;

// Inyectar el valor de Respuesta al movimiento (antes de armar el correo)
data['Respuesta al movimiento'] = action === 'accept' ? 'Aceptado' : 'Rechazado';

const isAccepted = action === 'accept';
const estado = isAccepted ? 'Aceptado' : 'Rechazado';
const subject = isAccepted ? '✅ Solicitud de movimiento ACEPTADA' : '❌ Solicitud de movimiento RECHAZADA';

let body = `La siguiente solicitud ha sido <strong>${estado}</strong>:<br><br>`;
body += '<table>';
for (const [clave, valor] of Object.entries(data)) {
  if (['action', 'row_number', 'email'].includes(clave)) continue;
  body += `<tr><td><strong>${clave}</strong></td><td>${valor ?? ''}</td></tr>`;
}
body += '</table>';

return [{
  json: {
    ...data,
    action: action,
    row_number: rowNumber,
    email: {
      to: 'example@example.com',
      subject: subject,
      body: body
    }
  }
}];

