      font-family: 'Segoe UI', Roboto, system-ui, -apple-system, sans-serif;
      background: linear-gradient(135deg, #f5f7fa 0%, #e9edf5 100%);
      min-height: 100vh;
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 20px;
    }
    .container {
      max-width: 480px;
      width: 100%;
      background: #ffffff;
      border-radius: 24px;
      padding: 40px 30px;
      box-shadow: 0 20px 60px rgba(0, 0, 0, 0.10), 0 8px 20px rgba(0, 0, 0, 0.06);
      text-align: center;
      transition: all 0.2s ease;
    }
    .icono {
      font-size: 64px;
      line-height: 1;
      margin-bottom: 16px;
    }
    h1 {
      font-size: 28px;
      font-weight: 700;
      margin-bottom: 12px;
      letter-spacing: -0.3px;
    }
    .aceptado { color: #0a7e3c; }
    .rechazado { color: #b91c1c; }
    .mensaje {
      font-size: 18px;
      color: #2d3748;
      margin-bottom: 8px;
    }
    .detalle {
      font-size: 15px;
      color: #4a5568;
      background: #f7fafc;
      border-radius: 12px;
      padding: 14px 20px;
      margin: 20px 0 8px;
      display: inline-block;
      border: 1px solid #e2e8f0;
    }
    .footer {
      margin-top: 28px;
      font-size: 13px;
      color: #a0aec0;
      border-top: 1px solid #edf2f7;
      padding-top: 20px;
    }
    .btn-cerrar {
      display: inline-block;
      margin-top: 16px;
      padding: 10px 28px;
      background: #2b6cb0;
      color: #fff;
      font-weight: 600;
      border-radius: 40px;
      text-decoration: none;
      font-size: 15px;
      transition: background 0.2s;
      border: none;
      cursor: pointer;
    }
    .btn-cerrar:hover {
      background: #1a4f7a;
    }
    @media (max-width: 480px) {
      .container { padding: 30px 20px; }
      h1 { font-size: 24px; }
      .icono { font-size: 52px; }
    }
  </style>
</head>
<body>
  <div class="container">
    <div class="icono">
      {{ $json.action === 'accept' ? '✅' : '❌' }}
    </div>

    <h1 class="{{ $json.action === 'accept' ? 'aceptado' : 'rechazado' }}">
      {{ $json.action === 'accept' ? 'Solicitud ACEPTADA' : 'Solicitud RECHAZADA' }}
    </h1>

    <p class="mensaje">
      {{ $json.action === 'accept' 
        ? 'El movimiento ha sido aprobado correctamente.' 
        : 'El movimiento ha sido rechazado.' }}
    </p>

    <div class="detalle">
      📋 Nº de solicitud: <strong>{{ $json.row_number || '—' }}</strong>
    </div>

    <button class="btn-cerrar" onclick="window.close()">
      Cerrar esta ventana
    </button>

    <div class="footer">
      Sistema de Gestión de Inventario &bull; Respuesta registrada
    </div>
  </div>
</body>
</html>
